                                                                                                                                                                                                                             
  CREATE TABLE "TENANT_DISPATCH_WORK_SCHEDULE"                                                                                                                                                                    
   (	"DISPATCH_WORK_SCHEDULE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                                  
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                       
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                                  
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                         
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                                    
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                         
	"START_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                          
	"DUTY_USER_COUNT" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                                   
	"DISPATCH_CONFIG_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                          
	"LAST_DISPATCH_SORT_NUM" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                  
	"ORG_ID" NUMBER,                                                                                                                                                                                                            
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                               
	 PRIMARY KEY ("DISPATCH_WORK_SCHEDULE_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE,                                                                                                                                                                                                       
	 FOREIGN KEY ("DISPATCH_CONFIG_ID")                                                                                                                                                                                         
	  REFERENCES "TENANT_DISPATCH_CONFIG" ("DISPATCH_CONFIG_ID") ON DELETE CASCADE ENABLE                                                                                                                            
   ) ;                                                                                                                                                                                                                       

